export function makeCrossword(entries){
 const cells=new Map(),placed=[],size=25,key=(r,c)=>`${r},${c}`;
 function fit(word,r,c,down){let crosses=0;const dr=down?1:0,dc=down?0:1;if(r<0||c<0||r+dr*word.length>=size||c+dc*word.length>=size)return -1;if(cells.has(key(r-dr,c-dc))||cells.has(key(r+dr*word.length,c+dc*word.length)))return -1;
 for(let i=0;i<word.length;i++){const row=r+dr*i,col=c+dc*i,old=cells.get(key(row,col));if(old){if(old.char!==word[i]||old.directions.has(down))return -1;crosses++}else if(cells.has(key(row+(down?0:1),col+(down?1:0)))||cells.has(key(row-(down?0:1),col-(down?1:0))))return -1}return crosses}
 function put(entry,r,c,down){const word=entry.answer.toLocaleUpperCase();for(let i=0;i<word.length;i++){const k=key(r+(down?i:0),c+(down?0:i));if(!cells.has(k))cells.set(k,{char:word[i],directions:new Set()});cells.get(k).directions.add(down)}placed.push({...entry,answer:word,r,c,down})}
 const sorted=[...entries].sort((a,b)=>b.answer.length-a.answer.length);put(sorted.shift(),12,Math.floor((size-entries.reduce((a,b)=>a.answer.length>b.answer.length?a:b).answer.length)/2),false);
 let pending=sorted;for(let round=0;round<3;round++){const missed=[];for(const entry of pending){let best=null;const word=entry.answer.toLocaleUpperCase();for(const [k,cell]of cells)for(let i=0;i<word.length;i++)if(word[i]===cell.char){const [row,col]=k.split(',').map(Number);for(const down of [false,true]){const r=row-(down?i:0),c=col-(down?0:i),score=fit(word,r,c,down);if(score>0&&(!best||score>best.score))best={r,c,down,score}}}if(best)put(entry,best.r,best.c,best.down);else missed.push(entry)}pending=missed}
 const points=[...cells.keys()].map(k=>k.split(',').map(Number)),minR=Math.min(...points.map(p=>p[0])),minC=Math.min(...points.map(p=>p[1]));const height=Math.max(...points.map(p=>p[0]))-minR+1,width=Math.max(...points.map(p=>p[1]))-minC+1;
 const starts=[...new Set(placed.map(p=>key(p.r,p.c)))].sort((a,b)=>{const [ar,ac]=a.split(',').map(Number),[br,bc]=b.split(',').map(Number);return ar-br||ac-bc});
 return {width,height,cells:points.map(([r,c])=>({r:r-minR,c:c-minC,char:cells.get(key(r,c)).char,number:starts.includes(key(r,c))?starts.indexOf(key(r,c))+1:null})),words:placed.map(p=>({...p,r:p.r-minR,c:p.c-minC,number:starts.indexOf(key(p.r,p.c))+1}))};
}
const word=(en,ru,ka)=>({en,ru,ka});
